package com.nexvary.imsi;
import android.app.*; import android.os.Bundle; import android.view.WindowManager; import android.widget.*; import java.util.*;
public class BaselinesActivity extends Activity {
 private LocalRepository repo; private boolean ar;
 @Override public void onCreate(Bundle b){ LanguageUtil.apply(this); super.onCreate(b); SecureScreenUtil.apply(this); repo=new LocalRepository(this); ar=LanguageUtil.current(this).equals("ar"); render(); }
 private void render(){ ScrollView s=new ScrollView(this); s.setClipToPadding(false); LinearLayout p=UiKit.page(this); s.addView(p); p.addView(UiKit.backButton(this)); p.addView(UiKit.eyebrow(this,"NEXVARY · TRUSTED ENVIRONMENTS")); p.addView(UiKit.title(this,ar?"إدارة خطوط الأساس":"Manage baselines")); p.addView(UiKit.body(this,ar?"احفظ فقط القياسات التي أجريتها في مكان ووقت تثق بهما. الضغط على أي عنصر يسمح بحذفه.":"Save baselines only in an environment and time you trust. Tap an entry to remove it.")); List<String> b=repo.baselines(); if(b.isEmpty())p.addView(UiKit.body(this,ar?"لا توجد خطوط أساس محفوظة.":"No trusted baselines saved.")); for(String x:new ArrayList<>(b)){ String[] z=x.split("\\|",2); String label=z.length>0?z[0]:x; Button v=UiKit.button(this,label); v.setOnClickListener(q->new AlertDialog.Builder(this).setTitle(ar?"حذف خط الأساس؟":"Remove baseline?").setMessage(label).setNegativeButton(ar?"إلغاء":"Cancel",null).setPositiveButton(ar?"حذف":"Remove",(d,w)->{List<String> now=repo.baselines(); now.remove(x); repo.saveBaselines(now); render();}).show()); p.addView(v); } setContentView(UiKit.withBottomNav(this,s,4)); }
}
